(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fr-CA"] = {"ui":{"skip":"Aller au contenu","back":"← Retour à AI-gile","lang.button":"Langue : {name}","lang.dialog":"Choisis une langue","lang.search":"Chercher une langue","lang.none":"Aucune langue ne correspond","lang.notYet":"{name} n'est pas encore traduit","theme.aria":"Passer du thème clair au thème sombre","theme.toLight":"Passer au thème clair","theme.toDark":"Passer au thème sombre","words.underline":"Souligner ces mots sur la page","words.underlineHelp":"Survole ou touche un mot en pointillés pour voir ce qu'il veut dire.","index.title":"AI-gile : ton équipe de dev IA, sur un seul tableau","index.description":"AI-gile est un tableau kanban pour les équipes de code IA. Elles travaillent pendant que tu dors; tu reçois une petite pile de choses à trancher, tester et accepter.","hero.logoAlt":"Icône du tableau AI-gile","hero.h1.html":"Ton équipe de dev IA, sur un seul&nbsp;tableau.","hero.alpha":"🐣 Pré-alpha fermée","hero.alphaTitle":"Tôt et inachevé : merci de l'essayer!","hero.lede":"Elles construisent pendant que tu dors. Au réveil, une petite pile t'attend : quelques questions, quelques choses à tester, un ou deux diamants violets. Un clic, c'est accepté, et retour à ton café.","dl.windows":"Appli Windows","dl.browser":"L'utiliser dans le navigateur","dl.soon":"Bientôt disponible","dl.notify":"🔔 Préviens-moi à l'ouverture","dl.notifySmall":"Alpha ou bêta","hero.secondary":"De l'agile, mais l'équipe n'a jamais besoin du café de la réunion debout. (Elle fait quand même la réunion.)","pitch.h2":"AI-gile en autant de mots que tu veux","pitch.lede":"Choisis une longueur, d'un mot à 144. Chaque longueur est sa propre description, écrite pour cette taille. Fais glisser le curseur ou utilise les flèches du clavier.","pitch.rangeLabel":"Longueur en mots","pitch.dice":"🎲 une autre version","pitch.words.one":"{n} mot","pitch.words.other":"{n} mots","pitch.letters.one":"{n} lettre","pitch.letters.other":"{n} lettres","pitch.chars.one":"{n} caractère","pitch.chars.other":"{n} caractères","count.line.html.one":"{n} carte sur le tableau en ce moment","count.line.html.other":"{n} cartes sur le tableau en ce moment","features.aria":"Ce qu'il fait","f.pile.h":"Une seule pile pour toi","f.pile.html":"<b>Pour toi</b> réunit tout ce qui t'attend, tous projets confondus : des questions, des choses à tester, des tâches que seul un humain peut faire. Ta file te dit ce qui vient ensuite et combien de temps ça prend.","f.sleep.h":"Des équipes qui travaillent pendant que tu dors","f.sleep.p":"Chaque projet a un chef et une équipe d'agents IA. Commente une carte et l'équipe se réveille, fait le travail, puis te le rend avec des étapes qu'un humain fatigué peut suivre.","f.tester.h":"Un testeur IA vérifie d'abord","f.tester.p":"Avant que quoi que ce soit n'arrive jusqu'à toi, un testeur suit les étapes dans une copie de l'appli et montre ce qu'il a vu, avec une capture d'écran. Feuillette celles qui sont passées et accepte d'un clic.","f.proof.h":"Des preuves, pas des promesses","f.proof.p":"Chaque remise montre ce qui a changé : les fichiers, le diff, les captures d'écran. Plus besoin d'ouvrir chaque appli pour savoir si c'est fini.","f.chat.h":"Clavarde avec tes chefs","f.chat.p":"Une colonne façon Discord : une icône par projet, des diamants violets pour ce qui a besoin de toi. Envoie une idée à un chef; il en fait des cartes et un plan, avec un bouton ✅ Go.","f.tidy.h":"Se range tout seul","f.tidy.p":"Les cartes liées fusionnent, les titres confus sont corrigés, et un contrôle des tokens garde le code léger. Moins de choses entre lesquelles jongler, moins à penser.","f.private.h":"À toi, sur ton ordinateur","f.private.li1":"Le tableau tourne sur ta propre machine et ne répond qu'à toi.","f.private.li2":"Les messages privés entre personnes sont chiffrés de bout en bout.","f.private.li3":"Pas de compte, pas de traceurs, pas de témoins.","f.lang.h":"Dans ta langue","f.lang.p":"Plus de 120 langues, du néerlandais, du gallois et du japonais au pirate, à Yoda et au klingon, avec un retour rapide à l'anglais pour les mots de développeur.","tl.aria":"Chronologie, de la première conversation à la feuille de route","tl.h2":"De la première discussion à la suite","tl.lede":"De vraies dates et heures, dans ton fuseau horaire. Après aujourd'hui, c'est le plan, sans date promise.","tl.today":"Aujourd'hui","tl.planned":"prévu","tl.cards.one":"{n} carte","tl.cards.other":"{n} cartes","join.h2":"Rejoins-nous","join.lede":"AI-gile est construit par un petit humain et un grand nombre d'agents patients. Pour l'instant c'est privé, en alpha fermée entre amis. Envie d'essayer quand ça s'ouvrira?","join.btn":"Je suis intéressé","join.small":"On t'écrira, rien d'autre","footer.tag":"AI-gile. Pas de traceurs, pas de témoins, pas de café de réunion debout.","footer.licence":"Licence professionnelle","footer.status":"État","footer.privacy":"Ce qu'on garde","form.sending":"Envoi…","form.failed":"Ça n'a pas marché : réessaie plus tard.","form.offline":"Impossible de joindre AI-gile : réessaie plus tard.","form.keep":"On s'en sert uniquement pour te répondre, puis on l'efface. Pas de traceurs, pas de cookies.","form.keepLink":"Ce qu'on garde","interest.title":"AI-gile : préviens-moi à l'ouverture de l'alpha","interest.description":"Laisse ton courriel pour savoir quand l'alpha ou la bêta fermée d'AI-gile s'ouvre.","interest.h1":"🔔 Préviens-moi à l'ouverture","interest.lede":"AI-gile est en pré-alpha fermée. Laisse ton courriel et on t'écrira une seule fois, quand il y aura une place pour toi.","interest.email":"Ton courriel","interest.which":"Quel test?","interest.alpha":"Alpha fermée : tôt, brut, beaucoup de changements","interest.beta":"Bêta : plus stable, plus tard","interest.both":"L'une ou l'autre, la première qui ouvre","interest.submit":"Inscris-moi sur la liste","interest.thanks":"Merci! Tu es sur la liste.","licence.title":"AI-gile : licence professionnelle","licence.description":"Tu utilises AI-gile dans ton activité? Demande une licence professionnelle gratuite.","licence.h1":"📜 Licence professionnelle","licence.lede":"Tu utilises AI-gile au travail? Dis-nous qui tu es et ce que tu fais. Si ça fait du bien, la licence est gratuite.","licence.company":"Entreprise","licence.website":"Site web","licence.what":"Ce que tu fais","licence.how":"En quoi ça aide le monde","licence.email":"Courriel","licence.submit":"Envoyer la demande","licence.thanks":"Merci! On te répondra par courriel.","status.title":"État d'AI-gile","status.h1":"État d'AI-gile","status.quiet":"Tout est calme","status.intro":"AI-gile fonctionne-t-il en ce moment ? Cette page vérifie le site, le partage de tableaux, les appels et le téléchargement toutes les 5 minutes.","status.up":"Fonctionne (réponse en {ms} ms)","status.slow":"N'a pas répondu à la dernière vérification, nouvel essai en cours","status.down":"En panne : n'a pas répondu aux deux dernières vérifications","status.svc.web":"Site web","status.svc.web.offers":"Ce site : ce qu'est AI-gile, et le formulaire d'intérêt","status.svc.boards":"Partage de tableaux","status.svc.boards.offers":"Tableaux publics, messages entre amis et invitations","status.svc.calls":"Appels","status.svc.calls.offers":"Voix, vidéo et partage d'écran dans AI-gile","status.svc.download":"Téléchargement","status.svc.download.offers":"L'installateur Windows et les liens d'invitation","status.checking":"Vérification…","status.offline":"Impossible de joindre le service d'état pour le moment (nouvel essai en cours)","status.updated":"mis à jour {ago}","status.justNow":"à l'instant","status.min":"il y a {n} min","status.hours":"il y a {n} h","status.days":"il y a {n} j","privacy.title":"AI-gile : ce qu'on garde","privacy.h1":"Ce qu'on garde","privacy.lede":"En bref : seulement ce que tu nous envoies, et pas longtemps.","privacy.only":"Seulement ce que tu nous envoies : ce que tu tapes dans un formulaire, comme ton e-mail. Rien d'autre sur toi.","privacy.sealed":"C'est scellé pour que notre serveur ne puisse pas le lire : dans ton navigateur, avant que ça parte (sur un navigateur plus ancien, dès que ça arrive). Seul notre propre tableau peut l'ouvrir.","privacy.server":"C'est effacé du serveur dès que ça atteint notre tableau. Tout ce qui s'y trouve encore au bout de 30 jours est effacé de toute façon.","privacy.board":"On le garde sur notre tableau seulement jusqu'à ce qu'on t'ait répondu, puis on l'efface là aussi.","privacy.none":"Pas de traceurs, pas de cookies, pas d'outils d'analyse.","privacy.local":"Ta langue et ton choix entre clair et sombre restent dans ton propre navigateur. Ils ne nous sont jamais envoyés.","privacy.ask":"Tu veux que ce soit effacé plus tôt ? Réponds à notre e-mail et dis-le-nous.","live.h2":"Regardez-le se construire, en direct","live.caption":"Chaque carte est masquée : vous voyez la forme du travail, pas les mots.","live.watching.one":"en direct : {n} spectateur","live.watching.other":"en direct : {n} spectateurs","live.last.now":"Dernière carte déplacée à l'instant","live.last.min.one":"Dernière carte déplacée il y a {n} min","live.last.min.other":"Dernière carte déplacée il y a {n} min","live.last.hour.one":"Dernière carte déplacée il y a {n} heure","live.last.hour.other":"Dernière carte déplacée il y a {n} heures","live.last.day.one":"Dernière carte déplacée il y a {n} jour","live.last.day.other":"Dernière carte déplacée il y a {n} jours","live.offline":"Le tableau en direct fait une petite pause. Revenez bientôt.","live.cols":"Backlog|À faire|En cours|L'équipe vérifie|À tester par toi|Pour l'équipe|Terminé"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Délégué."]},{"n":2,"texts":["Kanban robotique.","Agents, organisés.","Idées, réalisées."]},{"n":3,"texts":["Kanban pour robots.","Tes idées deviennent fonctionnalités.","Kanban d'agents gratuit."]},{"n":5,"texts":["Un tableau piloté par des agents.","Tu écris, les agents construisent.","Gratuit, local, testé, un peu fou."]},{"n":8,"texts":["Un kanban gratuit où travaillent des agents IA.","Écris une idée. Les agents construisent. Tu acceptes.","L'agile pour un humain et plein de robots patients."]},{"n":13,"texts":["Un tableau kanban sur ton ordinateur, où des agents IA prennent les cartes en charge.","Écris une idée. Une équipe d'agents la construit. Un testeur la vérifie.","Gratuit, sans compte, sans traceurs : un tableau, des robots, et toi aux commandes."]},{"n":21,"texts":["AI-gile est un tableau kanban pour travailler avec des agents de code IA. Ils prennent les cartes; toi, tu testes et tu acceptes.","Chaque projet reçoit un chef et une équipe d'agents IA. Commente n'importe quelle carte et l'équipe se met au travail.","Un tableau de tâches perso et gratuit, qui tourne sur ton propre ordinateur. Les ouvriers sont des robots. Celui qui dit oui, c'est toi."]},{"n":34,"texts":["Tu poses tes idées sur un tableau. Une équipe d'agents IA les transforme en fonctionnalités qui marchent, les teste et te les rend avec des étapes à essayer. Rien n'est terminé tant que tu ne l'as pas dit.","AI-gile est un tableau kanban fait maison, que Rich a construit avec beaucoup d'aide des agents qu'il gère maintenant. Il est gratuit, tourne sur ton ordinateur, et se partage entre amis, il ne se vend pas.","Imagine un tableau kanban tout simple, avec des colonnes du Backlog jusqu'à Terminé, sauf que les cartes sont prises par des agents IA. Ils donnent des nouvelles, posent des questions quand ils bloquent, et attendent toujours ton feu vert."]},{"n":55,"texts":["AI-gile est un tableau kanban dont l'équipe est faite d'agents IA. Chaque projet a un chef qui planifie le travail et des aides qui le construisent. Quand une fonctionnalité est prête, un testeur IA l'essaie et prend une capture d'écran, puis elle arrive dans ta pile. Accepte-la, ou commente et ils la retravaillent.","Tout a commencé comme la façon qu'avait une personne de suivre plein de sessions de code IA en même temps, puis c'est devenu un vrai tableau. Il tourne sur ta machine, ne demande aucun compte et n'a aucun traceur. Il est gratuit pour les amis et les curieux. Il est aussi inachevé : attends-toi à des aspérités et à quelques surprises.","Voici la version honnête. C'est toujours à toi d'avoir les idées, et toujours à toi de vérifier les résultats. Ce qu'AI-gile fait, c'est tout ce qu'il y a entre les deux : il garde les cartes en ordre, réveille le bon agent quand tu commentes, montre exactement ce qui a changé, et range tout ça dans une seule petite pile pour toi."]},{"n":89,"texts":["AI-gile est un tableau kanban gratuit que tu fais tourner sur ton propre ordinateur. Au lieu de personnes, chaque projet a une équipe d'agents IA : un chef qui transforme tes idées en cartes et en plan, et des aides qui prennent les cartes par ordre de priorité. Quand quelque chose est construit, un testeur IA suit les étapes de test et te montre ce qu'il a vu. Ensuite ça attend dans une pile appelée Pour toi. Tu l'acceptes, ou tu commentes et l'équipe retente sa chance. Rien n'arrive jamais dans Terminé sans toi.","Quelques fonctions que tu n'attends peut-être pas. Une veille de nuit garde la colonne À faire bien garnie pendant que tu dors, en choisissant des cartes qui n'ont pas besoin de ta réponse. Un compteur de tokens montre combien les agents ont consommé aujourd'hui et cette semaine, et le mode sans tokens leur dit d'arrêter de dépenser. Tu peux écrire à tes amis, et les messages privés sont chiffrés de bout en bout. Le tableau parle environ 120 langues, dont le néerlandais, le flamand, le pirate et le klingon. Rien de tout ça ne coûte un centime, et personne n'essaie de te le vendre non plus.","AI-gile est un petit projet personnel, pas une entreprise. Rich voulait s'occuper de plusieurs projets de code IA sans ouvrir chaque appli pour aller voir, alors lui et les agents ont construit un tableau pour ça, puis s'en sont servis pour construire le reste. Il est en pré-alpha fermée, ce qui veut dire qu'il fonctionne, à peu près, pour une poignée d'amis. Il n'y a ni page de tarifs, ni lettre d'information, ni plan de croissance. Si ça te semble utile, tu pourras demander à l'essayer quand il s'ouvrira un peu plus."]},{"n":144,"texts":["AI-gile est un tableau kanban pour un humain et beaucoup d'agents IA. Il tourne sur ton propre ordinateur et il est entièrement gratuit. Tu ajoutes des projets, et chaque projet reçoit un chef et une petite équipe. Tu discutes avec le chef, un peu comme sur Discord, et tu décris une idée; le chef en fait des cartes et un plan, puis attend que tu appuies sur Go. L'équipe déroule les cartes par ordre de priorité, avec une ligne de commande toute simple pensée pour les modèles de langage. Avant que quoi que ce soit ne te revienne, un testeur IA suit les étapes dans une copie de l'appli et joint une capture d'écran. Le travail terminé arrive dans ta pile avec les fichiers modifiés et le diff. Tu l'acceptes, ou tu laisses un commentaire et l'équipe se réveille et réessaie. Toi seul peux déplacer une carte vers Terminé.","Une journée avec AI-gile, en gros. Le soir, tu laisses quelques commentaires : ce bouton est mal placé, cette liste devrait être triée, on pourrait avoir un mode sombre. Tu vas te coucher. Les agents lisent les commentaires, font les changements, les testent et te les rendent. Si À faire se vide, la veille de nuit le remplit depuis le backlog avec des cartes qui n'ont pas besoin de ta réponse. Le matin, il y a une seule petite pile : deux ou trois questions et quelques choses à essayer, chacune avec des étapes qu'une personne ensommeillée peut suivre et une capture d'écran qui prouve que ça marche. Tu cliques, tu acceptes les bonnes et tu renvoies le reste. Un compteur de tokens montre ce que tout ça a coûté, et le mode sans tokens est là pour les semaines maigres. Ensuite tu prends ton déjeuner, ce que les agents ne savent pas encore faire pour toi.","D'abord, ce qu'AI-gile n'est pas. Ce n'est pas une start-up, ce n'est pas à vendre, et personne ne récolte tes données. C'est un tableau gratuit qui tourne sur ton ordinateur, sans compte, sans traceurs et sans témoins. Ce que c'est : un endroit bien rangé pour voir d'un coup tous tes projets de code IA, avec une équipe d'agents qui s'occupe des cartes et toi qui prends les décisions. Il fusionne les cartes liées, corrige les titres confus, et surveille que le code reste léger. Il parle environ 120 langues, du néerlandais et du flamand jusqu'au pirate et au klingon. Les amis peuvent s'écrire, en privé et chiffré. Il a été construit par Rich et un grand nombre d'agents patients, surtout en s'utilisant lui-même. Il est en pré-alpha fermée, donc il est un peu brut par endroits. Si ça te tente, demande gentiment et tu pourras entrer plus tôt que les autres."]}],"quips":{"1":"Un mot. Audacieux. Peut-être trop.","3":"Trois mots. Déjà plus honnête que la plupart des pages produit.","8":"Huit mots. Encore plus court qu'une réunion debout.","21":"Les longueurs sont des story points, au fait. Évidemment.","55":"Cinquante-cinq mots. Deux cartes ont été terminées pendant ta lecture.","144":"Voilà la longue. Il n'y a pas de 233. Les agents sont allés se coucher."}},"timeline":{"first-idea.name":"La première idée","first-idea.line":"La toute première conversation, avant la moindre ligne de code.","first-board.name":"Premier tableau","first-board.line":"Un tableau qui suit sa propre construction : cartes, colonnes, glisser-déposer, projets.","team-roles.name":"Équipe et rôles","team-roles.line":"Profils d'agents, modèles d'équipe, espaces et qui fait quoi.","install.name":"Installation et versions","install.line":"Un zip qu'un ami peut installer, mises à jour automatiques, canaux et retour en arrière.","usage-saver.name":"Économie d'usage","usage-saver.line":"Mesurer ce que coûtent les exécutions, garder le code léger, préserver ta limite.","friends.name":"Amis et partage","friends.line":"Messages privés, relais brouillé, invitations, rôles et projets partagés.","languages.name":"Langues","languages.line":"Chaque texte d'écran dans un fichier de langue, avec le néerlandais et le flamand en premier.","ai-tester.name":"Testeur IA","ai-tester.line":"Un testeur vérifie chaque remise d'abord et montre ce qu'il a vu.","website.name":"Le site web","website.line":"aigile.lol, la page teaser et cette chronologie.","streaming.name":"Clavardage et streaming","streaming.line":"Discord, Twitch, OBS, mode streamer, GIF et emojis.","no-ai.name":"Édition sans IA","no-ai.line":"Un tableau pour ceux qui codent sans IA, et des tableaux publics.","night-watch.name":"Veille de nuit","night-watch.line":"Un veilleur et un Scrum Master gardent les équipes sur la tâche pendant que tu dors.","p-more.name":"Tout le reste","p-more.line":"Des idées plus petites qui attendent encore leur tour.","p-android.name":"Téléphone et Android","p-android.line":"Accéder à ton tableau depuis un téléphone, puis une appli Android native.","p-release.name":"Alpha et après","p-release.line":"Alpha fermée, le site en ligne, puis la bêta.","p-languages.name":"Plus de langues","p-languages.line":"Plus d'une centaine de langues, et un mode immersion pour ceux qui apprennent.","p-engines.name":"Plus de moteurs IA","p-engines.line":"Choisis Claude, Codex ou Gemini pour chaque agent.","p-pro.name":"Pratiques pro","p-pro.line":"Étiquettes de risque, barrières de fusion, cartes d'incident et garde-fous.","p-self.name":"Prendre soin de toi","p-self.line":"Mode fatigué, rappels de bien-être et 4:20.","p-servers.name":"Serveurs et échelle","p-servers.line":"Réglages de serveur globaux, rôles et préparation de la croissance.","p-livestream.name":"Extras de streaming","p-livestream.line":"Chat Twitch, emojis personnalisés et vue publique en direct."},"words":{"button":"📖 Mots de dev","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Chercher un mot…","none":"Aucun mot ne correspond.","close":"Fermer","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Dépôt","text":"Le dossier de code du projet et tout son historique de commits, en général aussi conservé sur GitHub.","also":["repo","dépôts","repository"]},{"id":"branch","g":"build","word":"Branche","text":"Une ligne de travail séparée dans le code, pour pouvoir faire des changements sans toucher à la version principale.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Un instantané enregistré du code, avec une courte note sur ce qui a changé. Tu peux toujours revenir à l'un d'eux.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Envoyer les instantanés enregistrés (commits) de cet ordinateur vers GitHub, pour qu'ils soient sauvegardés et partagés."},{"id":"merge","g":"build","word":"Merge","text":"Réintégrer les changements d'une branche dans la version principale."},{"id":"pr","g":"build","word":"Pull request","text":"Demander que les changements d'une branche soient vérifiés et fusionnés dans la version principale.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactoring","text":"Ranger le code sans changer ce qu'il fait : fichiers plus petits, noms plus clairs, moins de répétition."},{"id":"bug","g":"build","word":"Bug","text":"Quelque chose qui ne fonctionne pas comme il devrait.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Essayer un travail terminé pour vérifier qu'il fait ce qui était demandé, avant de l'accepter.","also":["tests","tester","testé","testée","testés","testées"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Déploiement","text":"Mettre une nouvelle version en ligne, par exemple sur un serveur où les gens l'utilisent."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Des idées et du travail pas encore planifiés. Personne n'y touche tant que ça ne passe pas dans À faire."},{"id":"sprint","g":"team","word":"Sprint","text":"Une courte période de travail (souvent une ou deux semaines) avec un ensemble de cartes convenu à terminer.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Un point rapide : ce que chaque membre de l'équipe a fait, ce qu'il fait ensuite et ce qui le bloque.","also":["standup","stand-ups","stand up"]},{"id":"kanban","g":"team","word":"Kanban","text":"Un tableau avec des colonnes (À faire, En cours, Terminé) où les cartes passent de gauche à droite au fil du travail."},{"id":"wip","g":"team","word":"Limite WIP","text":"Travail en cours : le nombre maximal de cartes qu'une colonne devrait contenir, pour que l'équipe termine les choses avant d'en commencer d'autres.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Une IA qui travaille seule sur une tâche : elle lit le code, fait des changements, lance des vérifications et fait son rapport.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"L'unité dans laquelle on compte la consommation de l'IA : en gros, quelques lettres de texte lues ou écrites. Moins tu en utilises, plus il te reste de forfait.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Une petite commande qui s'exécute toute seule à un moment précis, par ex. au démarrage d'une session IA, pour que l'équipe entende tes commentaires.","also":["hooks"]}]}};
